const shows=[{day:'05',month:'DEC',dow:'SAT',name:'THE BLUE HOUR TRIO',detail:'Piano · bass · the space between',type:'instrumental',label:'INSTRUMENTAL',time:'8:30 PM',description:'A little swing, a little silence, and a trio that knows exactly when to leave room for the music.'},{day:'11',month:'DEC',dow:'FRI',name:'MARA & THE MOONLIGHT',detail:'A voice made for the last train home',type:'vocal',label:'VOCAL',time:'9:00 PM',description:'An intimate set of imaginary standards and songs for staying just a little longer.'},{day:'12',month:'DEC',dow:'SAT',name:'THE MIDNIGHT COLLECTIVE',detail:'A slow burn after the lights go low',type:'late',label:'LATE SET',time:'11:00 PM',description:'Loose, luminous, and a little unpredictable. A late set made for night owls.'},{day:'18',month:'DEC',dow:'FRI',name:'SLOW SIGNAL QUARTET',detail:'The sound of taking your time',type:'instrumental',label:'INSTRUMENTAL',time:'8:30 PM',description:'Four players trade stories in a set that moves from hushed to quietly electric.'},{day:'19',month:'DEC',dow:'SAT',name:'LOLA NORTH',detail:'Songs from the other side of midnight',type:'vocal',label:'VOCAL',time:'9:00 PM',description:'A fictional voice and a collection of imagined songs for the beautiful hours.'}];const list=document.querySelector('#showList');const dialog=document.querySelector('#booking');let lastTrigger=null;function render(filter='all'){list.innerHTML=shows.map((s,i)=>({s,i})).filter(({s})=>filter==='all'||s.type===filter).map(({s,i})=>`<article class="show"><div class="date"><strong>${s.day}</strong><span>${s.month}<br>${s.dow}</span></div><div><h3>${s.name}</h3><p>${s.detail}</p></div><span class="show-type">${s.label} · ${s.time}</span><button type="button" data-show="${i}" aria-label="View ${s.name} details">VIEW THE NIGHT</button></article>`).join('')};document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(el=>{el.classList.toggle('active',el===button);el.setAttribute('aria-pressed',String(el===button))});render(button.dataset.filter)}));list.addEventListener('click',e=>{const button=e.target.closest('[data-show]');if(!button)return;lastTrigger=button;const s=shows[Number(button.dataset.show)];document.querySelector('#dialogTitle').textContent=s.name;document.querySelector('#dialogMeta').textContent=`${s.dow} ${s.month} ${s.day} · ${s.time} · ${s.label}`;document.querySelector('#dialogDescription').textContent=s.description;document.querySelector('#feedback').textContent='This is a demo. No real reservation will be made.';document.querySelector('#guests').value='2';dialog.showModal();document.querySelector('#closeDialog').focus()});document.querySelector('#closeDialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('close',()=>lastTrigger?.focus());document.querySelector('#bookingForm').addEventListener('submit',e=>{e.preventDefault();let n=document.querySelector('#guests').value;document.querySelector('#feedback').textContent=`Preview for ${n} ${n==='1'?'guest':'guests'}. This is a demo; no reservation has been made.`});render();
